/// Find related sessions for a given source path.
/// Returns sessions that share the same workspace, same day, or same agent.
///
/// The second tuple element (agent_id) is Option<i64> because legacy V1
/// conversations may have NULL agent_id.  Callers that want to filter by
/// "same agent" should skip that filter when agent_id is None.
#[allow(clippy::type_complexity)]
pub(crate) fn find_context_source_conversation(
    conn: &crate::franken_sync::Connection,
    path_str: &str,
    source_id: Option<&str>,
) -> Option<(
    i64,
    Option<i64>,
    Option<i64>,
    Option<i64>,
    String,
    String,
    String,
)> {
    use crate::franken_sync::compat::{ConnectionExt, ParamValue, RowExt};

    let normalized_source_sql = normalized_source_identity_sql_expr("c.source_id", "c.origin_host");
    let source_id = canonical_followup_source_id(source_id);
    if let Some(source_id) = source_id.as_deref() {
        // LEFT JOIN + COALESCE on agents: find_context_source_conversation
        // must return the most-recent matching conversation even if it has a
        // legacy NULL agent_id (V1 schema).
        let query = format!(
            "SELECT c.id, c.agent_id, c.workspace_id, c.started_at, c.title, COALESCE(a.slug, 'unknown'), {normalized_source_sql}
             FROM conversations c
             LEFT JOIN agents a ON c.agent_id = a.id
             WHERE c.source_path = ? AND {normalized_source_sql} = ?
             ORDER BY c.started_at DESC
             LIMIT 1"
        );
        return conn
            .query_row_map(
                &query,
                &[ParamValue::from(path_str), ParamValue::from(source_id)],
                |r: &crate::franken_sync::Row| {
                    Ok((
                        r.get_typed(0)?,
                        r.get_typed(1)?,
                        r.get_typed(2)?,
                        r.get_typed(3)?,
                        r.get_typed::<Option<String>>(4)?.unwrap_or_default(),
                        r.get_typed(5)?,
                        r.get_typed(6)?,
                    ))
                },
            )
            .ok();
    }

    let query = format!(
        "SELECT c.id, c.agent_id, c.workspace_id, c.started_at, c.title, COALESCE(a.slug, 'unknown'), {normalized_source_sql}
         FROM conversations c
         LEFT JOIN agents a ON c.agent_id = a.id
         WHERE c.source_path = ?
         ORDER BY CASE WHEN {normalized_source_sql} = '{local}' THEN 0 ELSE 1 END, c.started_at DESC
         LIMIT 1",
        local = crate::sources::provenance::LOCAL_SOURCE_ID,
    );
    conn.query_row_map(
        &query,
        &[ParamValue::from(path_str)],
        |r: &crate::franken_sync::Row| {
            Ok((
                r.get_typed(0)?,
                r.get_typed(1)?,
                r.get_typed(2)?,
                r.get_typed(3)?,
                r.get_typed::<Option<String>>(4)?.unwrap_or_default(),
                r.get_typed(5)?,
                r.get_typed(6)?,
            ))
        },
    )
    .ok()
}


pub(crate) const CONTEXT_CANDIDATES_SQL: &str = "SELECT id, workspace_id, agent_id, started_at FROM conversations INDEXED BY idx_conversations_context";


#[derive(Debug)]
pub(crate) struct ContextCandidate {
    pub(crate) id: i64,
    pub(crate) workspace_id: Option<i64>,
    pub(crate) agent_id: Option<i64>,
    pub(crate) started_at: Option<i64>,
}


pub(crate) fn context_related_ids(
    conn: &crate::franken_sync::Connection,
    source: &ContextCandidate,
    limit: usize,
) -> CliResult<[Vec<i64>; 3]> {
    use crate::franken_sync::compat::{ConnectionExt, RowExt};

    let mut groups: [Vec<i64>; 3] = Default::default();
    if limit == 0
        || (source.workspace_id.is_none()
            && source.agent_id.is_none()
            && source.started_at.is_none())
    {
        return Ok(groups);
    }
    let has_index = !conn
        .query("SELECT name FROM sqlite_master WHERE type = 'index' AND name = 'idx_conversations_context'")
        .map_err(|e| CliError::unknown(format!("context index lookup: {e}")))?
        .is_empty();
    // V21 is installed by the normal writable storage migration. Context must
    // remain read-only and usable before that migration, too.
    let sql = if has_index {
        CONTEXT_CANDIDATES_SQL
    } else {
        "SELECT id, workspace_id, agent_id, started_at FROM conversations"
    };
    // In fsqlite 0.3.18 a WHERE on the ordered-index path still reads the
    // conversation record. An unfiltered covering walk avoids every metadata
    // overflow chain. Filter these small keys here, then hydrate only results.
    let mut candidates = conn
        .query_map_collect(sql, &[], |row| {
            Ok(ContextCandidate {
                id: row.get_typed(0)?,
                workspace_id: row.get_typed(1)?,
                agent_id: row.get_typed(2)?,
                started_at: row.get_typed(3)?,
            })
        })
        .map_err(|e| CliError::unknown(format!("context candidates: {e}")))?;
    // DESC puts NULL timestamps last. Give previously unspecified ties a
    // stable rowid order, independent of the index's other key columns.
    candidates.sort_unstable_by(|a, b| b.started_at.cmp(&a.started_at).then(a.id.cmp(&b.id)));
    let day_start = source.started_at.map(|ts| i128::from(ts - ts % 86_400_000));
    for candidate in candidates {
        if candidate.id == source.id {
            continue;
        }
        let matches = [
            source.workspace_id.is_some() && candidate.workspace_id == source.workspace_id,
            day_start
                .zip(candidate.started_at)
                .is_some_and(|(start, ts)| (start..start + 86_400_000).contains(&i128::from(ts))),
            source.agent_id.is_some() && candidate.agent_id == source.agent_id,
        ];
        for (group, matches) in groups.iter_mut().zip(matches) {
            if matches && group.len() < limit {
                group.push(candidate.id);
            }
        }
    }
    Ok(groups)
}


pub(crate) fn run_context(
    path: &Path,
    source_id: Option<&str>,
    data_dir_override: &Option<PathBuf>,
    db_override: Option<PathBuf>,
    output_format: Option<RobotFormat>,
    limit: usize,
) -> CliResult<()> {
    use crate::franken_sync::compat::{ConnectionExt, OptionalExtension, ParamValue, RowExt};

    let conn = open_franken_analytics_db(data_dir_override, db_override.as_ref())?;

    if let Some(source_id) = source_id {
        validate_followup_source_id(source_id, "cass context")?;
    }

    // Keep selection and hydration on one archive snapshot even if an indexer
    // commits between reads. Dropping the connection rolls back on any error.
    conn.execute("BEGIN DEFERRED;")
        .map_err(|e| CliError::unknown(format!("context read snapshot: {e}")))?;

    // Find the source conversation by path (normalized to string)
    let path_str = path.to_string_lossy().to_string();
    let source_conv = find_context_source_conversation(&conn, &path_str, source_id);

    let Some((conv_id, agent_id, workspace_id, started_at, title, agent_slug, selected_source_id)) =
        source_conv
    else {
        return Err(CliError {
            code: 4,
            kind: CliErrorKind::NotFound.kind_str(),
            message: match source_id {
                Some(source_id) => format!("No session found at path: {path_str} for source '{source_id}'"),
                None => format!("No session found at path: {path_str}"),
            },
            hint: Some(match source_id {
                Some(_) => "Use the exact source_id from search output or omit --source to prefer the local session.".to_string(),
                None => "Use 'cass search' to find sessions, then use the source_path from results.".to_string(),
            }),
            retryable: false,
        });
    };

    // Get workspace path for display
    let workspace_path: Option<String> = workspace_id.and_then(|ws_id: i64| {
        conn.query_row_map(
            "SELECT path FROM workspaces WHERE id = ?",
            &[ParamValue::from(ws_id)],
            |r: &crate::franken_sync::Row| r.get_typed(0),
        )
        .ok()
    });

    let normalized_source_sql = normalized_source_identity_sql_expr("c.source_id", "c.origin_host");

    let [workspace_ids, day_ids, agent_ids] = context_related_ids(
        &conn,
        &ContextCandidate {
            id: conv_id,
            workspace_id,
            agent_id,
            started_at,
        },
        limit,
    )?;
    // A direct rowid lookup avoids the planner's join/sort table scans. Cache
    // overlapping results so each selected wide row is read at most once.
    type RelatedSession = (String, String, String, Option<i64>, String);
    let mut hydrated: HashMap<i64, RelatedSession> = HashMap::new();
    let query = format!(
        "SELECT c.source_path, c.title, c.agent_id, c.started_at, {normalized_source_sql}
         FROM conversations c WHERE c.id = ?1"
    );
    let mut hydrate = |ids: Vec<i64>| -> CliResult<Vec<RelatedSession>> {
        ids.into_iter()
            .map(|id| {
                if let Some(row) = hydrated.get(&id) {
                    return Ok(row.clone());
                }
                let (path, title, agent_id, started_at, source_id) = conn
                    .query_row_map(&query, &[ParamValue::from(id)], |row| {
                        Ok((
                            row.get_typed::<String>(0)?,
                            row.get_typed::<Option<String>>(1)?.unwrap_or_default(),
                            row.get_typed::<Option<i64>>(2)?,
                            row.get_typed::<Option<i64>>(3)?,
                            row.get_typed::<String>(4)?,
                        ))
                    })
                    .map_err(|e| CliError::unknown(format!("context session {id}: {e}")))?;
                let agent: Option<String> = if let Some(agent_id) = agent_id {
                    conn.query_row_map(
                        "SELECT COALESCE(slug, 'unknown') FROM agents WHERE id = ?1",
                        &[ParamValue::from(agent_id)],
                        |row| row.get_typed(0),
                    )
                    .optional()
                    .map_err(|e| CliError::unknown(format!("context agent: {e}")))?
                } else {
                    None
                };
                let row = (
                    path,
                    title,
                    agent.unwrap_or_else(|| "unknown".into()),
                    started_at,
                    source_id,
                );
                hydrated.insert(id, row.clone());
                Ok(row)
            })
            .collect()
    };
    let same_workspace = hydrate(workspace_ids)?;
    let same_day = hydrate(day_ids)?;
    let same_agent: Vec<_> = hydrate(agent_ids)?
        .into_iter()
        .map(|(path, title, _, started_at, source_id)| (path, title, started_at, source_id))
        .collect();
    conn.execute("ROLLBACK;")
        .map_err(|e| CliError::unknown(format!("context release snapshot: {e}")))?;

    let structured_format = output_format.or_else(robot_format_from_env).map(|fmt| {
        if matches!(fmt, RobotFormat::Sessions) {
            RobotFormat::Compact
        } else {
            fmt
        }
    });

    if let Some(fmt) = structured_format {
        let format_ts = |ts: Option<i64>| -> Option<String> {
            ts.and_then(|t| chrono::DateTime::from_timestamp_millis(t).map(|d| d.to_rfc3339()))
        };

        let payload = serde_json::json!({
            "source": {
                "path": path_str,
                "source_id": selected_source_id,
                "title": title,
                "agent": agent_slug,
                "workspace": workspace_path,
                "started_at": format_ts(started_at),
            },
            "related": {
                "same_workspace": same_workspace.iter().map(|(p, t, a, ts, source_id)| {
                    serde_json::json!({
                        "path": p,
                        "source_id": source_id,
                        "title": t,
                        "agent": a,
                        "started_at": format_ts(*ts),
                    })
                }).collect::<Vec<_>>(),
                "same_day": same_day.iter().map(|(p, t, a, ts, source_id)| {
                    serde_json::json!({
                        "path": p,
                        "source_id": source_id,
                        "title": t,
                        "agent": a,
                        "started_at": format_ts(*ts),
                    })
                }).collect::<Vec<_>>(),
                "same_agent": same_agent.iter().map(|(p, t, ts, source_id)| {
                    serde_json::json!({
                        "path": p,
                        "source_id": source_id,
                        "title": t,
                        "started_at": format_ts(*ts),
                    })
                }).collect::<Vec<_>>(),
            },
            "counts": {
                "same_workspace": same_workspace.len(),
                "same_day": same_day.len(),
                "same_agent": same_agent.len(),
            }
        });
        return output_structured_value(payload, fmt);
    }

    use colored::Colorize;

    println!("{}", "Session Context".bold().cyan());
    println!("{}", "===============".cyan());
    println!();
    println!("{}: {}", "Source".bold(), path_str);
    println!("  Source ID: {}", selected_source_id.as_str().magenta());
    println!("  Title: {}", title.as_str().yellow());
    println!("  Agent: {}", agent_slug.as_str().green());
    if let Some(ws) = &workspace_path {
        println!("  Workspace: {}", ws.as_str().blue());
    }
    if let Some(ts) = started_at
        && let Some(dt) = chrono::DateTime::from_timestamp_millis(ts)
    {
        println!("  Started: {}", dt.format("%Y-%m-%d %H:%M:%S"));
    }
    println!();

    if !same_workspace.is_empty() {
        println!(
            "{} ({}):",
            "Same Workspace".bold().blue(),
            same_workspace.len()
        );
        for (path, title_str, agent, timestamp, source_id) in &same_workspace {
            let ts_str = timestamp
                .and_then(chrono::DateTime::from_timestamp_millis)
                .map(|d| d.format("%Y-%m-%d %H:%M").to_string())
                .unwrap_or_default();
            println!(
                "  • {} [{} @ {}] {}",
                title_str.as_str().yellow(),
                agent.as_str().green(),
                source_id.as_str().magenta(),
                ts_str.dimmed()
            );
            println!("    {}", path.as_str().dimmed());
        }
        println!();
    }

    if !same_day.is_empty() {
        println!("{} ({}):", "Same Day".bold().magenta(), same_day.len());
        for (path, title_str, agent, timestamp, source_id) in &same_day {
            let ts_str = timestamp
                .and_then(chrono::DateTime::from_timestamp_millis)
                .map(|d| d.format("%H:%M").to_string())
                .unwrap_or_default();
            println!(
                "  • {} [{} @ {}] {}",
                title_str.as_str().yellow(),
                agent.as_str().green(),
                source_id.as_str().magenta(),
                ts_str.dimmed()
            );
            println!("    {}", path.as_str().dimmed());
        }
        println!();
    }

    if !same_agent.is_empty() {
        println!("{} ({}):", "Same Agent".bold().green(), same_agent.len());
        for (path, title_str, timestamp, source_id) in &same_agent {
            let ts_str = timestamp
                .and_then(chrono::DateTime::from_timestamp_millis)
                .map(|d| d.format("%Y-%m-%d %H:%M").to_string())
                .unwrap_or_default();
            println!(
                "  • {} [{}] {}",
                title_str.as_str().yellow(),
                source_id.as_str().magenta(),
                ts_str.dimmed()
            );
            println!("    {}", path.as_str().dimmed());
        }
        println!();
    }

    if same_workspace.is_empty() && same_day.is_empty() && same_agent.is_empty() {
        println!("{}", "No related sessions found.".dimmed());
    }

    Ok(())
}


/// The binary's compiled completed-source reuse policy (GH#426). Reuse is
/// compiled in only when every dependency in the build's `Cargo.lock` has a
/// registry or git source: a local path dependency or `[patch]` can change a
/// parser without changing the lockfile, so such a build reparses every
/// source on every incremental run. Release binaries have it enabled.
#[derive(Debug, Clone, Serialize, PartialEq, Eq)]
pub struct SourceIngestReuseCapability {
    pub enabled: bool,
    /// The first unpinned package that disabled reuse; `None` when enabled.
    pub disabled_by: Option<String>,
}


impl SourceIngestReuseCapability {
    pub(crate) fn compiled() -> Self {
        let blocker = env!("CASS_SOURCE_INGEST_REUSE_BLOCKER");
        Self {
            enabled: env!("CASS_SOURCE_INGEST_REUSE") == "true",
            disabled_by: (!blocker.is_empty()).then(|| blocker.to_string()),
        }
    }
}
